def grid_islands(grid: list[str]) -> list[int]:
    if not grid:
        return []
    rows = len(grid)
    cols = len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    sizes = []
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == '#' and not visited[i][j]:
                stack = [(i, j)]
                visited[i][j] = True
                size = 0
                while stack:
                    x, y = stack.pop()
                    size += 1
                    for dx, dy in dirs:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < rows and 0 <= ny < cols:
                            if grid[nx][ny] == '#' and not visited[nx][ny]:
                                visited[nx][ny] = True
                                stack.append((nx, ny))
                sizes.append(size)
    sizes.sort(reverse=True)
    return sizes
