def bracket_depth(s: str) -> int:
    """
    Returns the maximal nesting depth of correctly matched brackets in the string.
    If the brackets are not properly matched, returns -1.
    Brackets considered are (), [], {}. All other characters are ignored.
    """
    stack = []
    max_depth = 0
    opening = {'(', '[', '{'}
    closing_map = {')': '(', ']': '[', '}': '{'}

    for ch in s:
        if ch in opening:
            stack.append(ch)
            current_depth = len(stack)
            if current_depth > max_depth:
                max_depth = current_depth
        elif ch in closing_map:
            if not stack or stack[-1] != closing_map[ch]:
                return -1
            stack.pop()
    if stack:
        return -1
    return max_depth
