def bracket_depth(s: str) -> int:
    """
    Returns the maximum nesting depth of correctly matched brackets in s.
    If the brackets are not properly balanced or mismatched, returns -1.
    Non-bracket characters are ignored. If there are no brackets, returns 0.
    """
    stack = []
    max_depth = 0
    opening = {'(', '[', '{'}
    closing = {')': '(', ']': '[', '}': '{'}

    for ch in s:
        if ch in opening:
            stack.append(ch)
            if len(stack) > max_depth:
                max_depth = len(stack)
        elif ch in closing:
            if not stack or stack[-1] != closing[ch]:
                return -1
            stack.pop()
    if stack:
        return -1
    return max_depth
